INSERT INTO public.eventos_evento (id, nome, descricao, total_vagas, data_inicio_inscricao, data_fim_inscricao, data_inicio_evento, data_fim_evento, criado_em, atualizado_em, status_id) VALUES (11, 'Montagem de Computador', 'Um curso de montagem de computador capacita alunos a montar, configurar e realizar manutenção preventiva/corretiva em desktops e notebooks, abordando desde a identificação de hardware (processador, placa-mãe, memória, SSD) até a instalação de sistemas operacionais e diagnósticos de defeitos', 40, '2026-02-23 06:00:00-03', '2026-02-27 18:00:00-03', '2026-03-02', '2026-03-13', '2026-02-13 15:51:31.245408-03', '2026-03-18 16:34:29.44661-03', 7);
INSERT INTO public.eventos_evento (id, nome, descricao, total_vagas, data_inicio_inscricao, data_fim_inscricao, data_inicio_evento, data_fim_evento, criado_em, atualizado_em, status_id) VALUES (2, 'Inglês Instrumental', 'O que é Lorem Ipsum?
Lorem Ipsum é simplesmente um texto fictício da indústria tipográfica e de impressão. Lorem Ipsum tem sido o texto fictício padrão da indústria desde os anos 1500, quando um impressor desconhecido pegou uma bandeja de tipos e os misturou para criar um livro de amostras de tipos. Ele sobreviveu não apenas a cinco séculos, mas também à transição para a editoração eletrônica, permanecendo essencialmente inalterado. Foi popularizado na década de 1960 com o lançamento de folhas Letraset contendo passagens de Lorem Ipsum e, mais recentemente, com softwares de editoração eletrônica como o Aldus PageMaker, que incluíam versões de Lorem Ipsum.

Por que o utilizamos?
É um fato conhecido que um leitor se distrairá com o conteúdo legível de uma página ao analisar seu layout. A vantagem de usar Lorem Ipsum é que ele possui uma distribuição de letras mais ou menos normal, ao contrário de usar frases como "Conteúdo aqui, conteúdo aqui", que o fazem parecer inglês legível. Muitos programas de editoração eletrônica e editores de páginas web agora usam Lorem Ipsum como texto padrão, e uma busca por "lorem ipsum" revelará muitos sites ainda em desenvolvimento. Diversas versões surgiram ao longo dos anos, algumas por acidente, outras propositalmente (com a inserção de humor, por exemplo).', 25, '2025-12-17 17:33:09-03', '2026-02-25 17:33:09-03', '2026-03-23', '2026-06-15', '2026-01-16 17:33:09.233392-03', '2026-05-19 11:37:28.511384-03', 6);


